#!/usr/bin/env python3
"""Generate PhET VR question batch JSON files (batch3–batch5)."""
import json
from pathlib import Path

BASE = Path(__file__).resolve().parents[1] / "data" / "questions"
PHET_URL = "https://phet.colorado.edu/sims/html/{slug}/latest/{slug}_en.html"


def entry(slug, name, subject, tie, questions):
    return {
        "external_url": PHET_URL.format(slug=slug),
        "phet_slug": slug,
        "question_bank": {
            "title": f"{name} — {subject} Assessment",
            "description": tie,
            "time_limit": 15,
            "passing_score": 60,
            "is_active": False,
        },
        "questions": questions,
    }


def mcq(order, text, options, answer, explanation):
    return {
        "order": order,
        "question_type": "mcq",
        "question_text": text,
        "options": options,
        "correct_answer": answer,
        "explanation": explanation,
        "points": 1,
    }


def tf(order, text, answer, explanation):
    return {
        "order": order,
        "question_type": "true_false",
        "question_text": text,
        "correct_answer": answer,
        "explanation": explanation,
        "points": 1,
    }


def short(order, text, answer, explanation):
    return {
        "order": order,
        "question_type": "short_answer",
        "question_text": text,
        "correct_answer": answer,
        "explanation": explanation,
        "points": 1,
    }


def write_file(filename, entries):
    path = BASE / filename
    path.write_text(json.dumps(entries, indent=2, ensure_ascii=False) + "\n")
    print(f"Wrote {path.name}: {len(entries)} experiments, {sum(len(e['questions']) for e in entries)} questions")


